import urllib.request,json
base='http://127.0.0.1:17448'
result={}
for route,key in [('/api/supervisor-watchdog/managed-chats','chats'),('/api/supervisor-watchdog/agent-assignments','assignments')]:
 try:
  with urllib.request.urlopen(base+route,timeout=6) as f:d=json.load(f)
  result[key]={'keys':sorted(d)[:24],'error':None}
  if key=='chats':
   rows=d.get('chats',d.get('managedChats',[]))
   result[key]['count']=len(rows) if isinstance(rows,list) else None
   result[key]['rows']=[{k:x.get(k) for k in ['id','managedChatId','chatId','title','profileId','provider','status','url','tabCount','activeAssignmentCount','lastSeenAt'] if x.get(k) is not None} for x in rows[:12]] if isinstance(rows,list) else []
  else:
   rows=d.get('assignments',[])
   statuses={}
   for x in rows:statuses[str(x.get('state'))]=statuses.get(str(x.get('state')),0)+1
   result[key]['count']=len(rows)
   result[key]['statuses']=statuses
   result[key]['queued']=[{k:x.get(k) for k in ['id','state','managedChatId','targetChatId','targetProfileId','dispatchCount','dispatchSubmitAttempted','lastPreflightReason','lastPreflightAt'] if x.get(k) is not None} for x in rows if x.get('state')=='queued'][:3]
 except Exception as e:result[key]={'error':type(e).__name__}
print(json.dumps({'result':result,'readOnly':True,'noProviderTextRead':True},ensure_ascii=True)[:7000])
